import { parseIso } from "./date";
import type { MemberAbsence } from "@/types/member";

/**
 * Pure time-window checks for `MemberAbsence`. The interval is
 * `[startsAt, endsAt)` — the start instant counts as away, the end does not.
 */

/** True while `at` falls inside the absence window. */
export function isAbsenceActive(absence: MemberAbsence, at: Date): boolean {
  return (
    parseIso(absence.startsAt).getTime() <= at.getTime() &&
    at.getTime() < parseIso(absence.endsAt).getTime()
  );
}

/** True once `at` has reached or passed `endsAt`. */
export function hasAbsenceEnded(absence: MemberAbsence, at: Date): boolean {
  return at.getTime() >= parseIso(absence.endsAt).getTime();
}

