/** The stored absence for one member, regardless of whether it has started or ended. */
export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toAbsence(row) : null;
}

/** The stored absence, but only when `at` actually falls inside its window. */
export async function findActiveAbsence(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<MemberAbsence | null> {
  const absence = await findAbsence(orgId, userId);
  if (!absence || !isAbsenceActive(absence, at)) return null;
  return absence;
}

/** Setting an absence again replaces the last one — one live row per member. */
export async function upsertAbsence(input: {
  orgId: OrgId;
  userId: UserId;
  delegateUserId: UserId | null;
  startsAt: IsoTimestamp;
  endsAt: IsoTimestamp;
  note: string | null;
}): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      delegateUserId: input.delegateUserId,
      startsAt: input.startsAt,
      endsAt: input.endsAt,
      note: input.note,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: input.delegateUserId,
        startsAt: input.startsAt,
        endsAt: input.endsAt,
        note: input.note,
        updatedAt: stamp,
      },
    })
    .returning()
    .get();

  return toAbsence(row);
}

export async function deleteAbsence(orgId: OrgId, userId: UserId): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Drops a delegate from any absence that names them, without touching the
 * absence itself — used when the delegate leaves the workspace so nothing
 * stays redirected to someone who is gone.
 */
export async function clearDelegateReferences(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

