/** The recipient for a currently-away user's own alert: their delegate, or themselves without one. */
async function redirectToDelegate(orgId: OrgId, userId: UserId): Promise<UserId> {
  const absence = await memberRepo.findActiveAbsence(orgId, userId, new Date());
  return absence?.delegateUserId ?? userId;
}

/** Mentioned users plus the delegate of any of them who is currently away. */
async function withDelegates(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  const now = new Date();
  const expanded = [...userIds];

  for (const userId of userIds) {
    const absence = await memberRepo.findActiveAbsence(orgId, userId, now);
    if (absence?.delegateUserId) expanded.push(absence.delegateUserId);
  }

  return expanded;
}

