import type { Tenant } from "./server/_support/fixtures";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("absence-manual", "growth");
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

describe("manual absence verification", () => {
  it("set/get/clear basics + validation + permissions", async () => {
    const now = new Date();
    const start = new Date(now.getTime() - 60_000).toISOString();
    const end = new Date(now.getTime() + 60_000).toISOString();

    // member without the right cannot set someone else's absence
    await expect(
      memberService.setAbsence(tenant.actors.member, {
        orgId: tenant.org.id,
        userId: tenant.userIds.viewer,
        delegateUserId: null,
        startsAt: start,
        endsAt: end,
        note: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // self-service is fine regardless of role
    const own = await memberService.setAbsence(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      startsAt: start,
      endsAt: end,
      note: "on vacation",
    });
    expect(own.delegateUserId).toBe(tenant.userIds.admin);

    // admin can set for others (has member:update_role)
    const setByAdmin = await memberService.setAbsence(tenant.actors.admin, {
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.owner,
      startsAt: start,
      endsAt: end,
      note: null,
    });
    expect(setByAdmin.delegateUserId).toBe(tenant.userIds.owner);

    // invalid range
    await expect(
      memberService.setAbsence(tenant.actors.viewer, {
        orgId: tenant.org.id,
        userId: tenant.userIds.viewer,
        delegateUserId: null,
        startsAt: end,
        endsAt: start,
        note: null,
      }),
    ).rejects.toThrow();

    // delegate cannot be self
    await expect(
      memberService.setAbsence(tenant.actors.viewer, {
        orgId: tenant.org.id,
        userId: tenant.userIds.viewer,
        delegateUserId: tenant.userIds.viewer,
        startsAt: start,
        endsAt: end,
        note: null,
      }),
    ).rejects.toThrow();

    // unknown member -> NotFoundError
    await expect(
      memberService.setAbsence(tenant.actors.owner, {
        orgId: tenant.org.id,
        userId: "01HZZZNOBODYNOBODYNOBODY1" as UserId,
        delegateUserId: null,
        startsAt: start,
        endsAt: end,
        note: null,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    // cross-tenant orgId -> TenantScopeError
    const other = await createTenant("absence-manual-other", "growth");
    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.viewer),
    ).rejects.toBeInstanceOf(TenantScopeError);

    // getAbsence resolves for anyone in the workspace
    const read = await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member);
    expect(read?.delegateUserId).toBe(tenant.userIds.owner);

    // clear
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member)).toBeNull();
    // clearing again is a no-op
    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
  });

  it("scheduled (future) absence is still returned by getAbsence, ended absence is null", async () => {
    const future = new Date(Date.now() + 3600_000);
    const farFuture = new Date(Date.now() + 7200_000);
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.owner,
      delegateUserId: null,
      startsAt: future.toISOString(),
      endsAt: farFuture.toISOString(),
      note: null,
    });
    const scheduled = await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.owner);
    expect(scheduled).not.toBeNull();

    const past1 = new Date(Date.now() - 7200_000);
    const past2 = new Date(Date.now() - 3600_000);
    await memberService.setAbsence(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.owner,
      delegateUserId: null,
      startsAt: past1.toISOString(),
      endsAt: past2.toISOString(),
      note: null,
    });
    const ended = await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.owner);
    expect(ended).toBeNull();
  });

  it("redirects assignment to the delegate while away, and self-assign is never redirected", async () => {
    const now = new Date();
    const start = new Date(now.getTime() - 60_000).toISOString();
    const end = new Date(now.getTime() + 60_000).toISOString();

    await memberService.setAbsence(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      startsAt: start,
      endsAt: end,
      note: null,
    });

    // assignIssue redirect
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Assign while away" }),
    );

    const assigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(assigned.assigneeId).toBe(tenant.userIds.admin);

    // createIssue redirect
    const createdWithAssignee = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Create while away",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    expect(createdWithAssignee.assigneeId).toBe(tenant.userIds.admin);

    // taking it myself is never redirected, even while away
    const selfTaken = await issueService.assignIssue(tenant.actors.viewer, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(selfTaken.assigneeId).toBe(tenant.userIds.viewer);

    // no chaining: viewer's delegate (admin) is also away -> stays with admin
    await memberService.setAbsence(tenant.actors.admin, {
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      delegateUserId: tenant.userIds.owner,
      startsAt: start,
      endsAt: end,
      note: null,
    });
    const chained = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(chained.assigneeId).toBe(tenant.userIds.admin);

    await memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.admin);
    await memberService.clearAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer);
  });

  it("overdue alert goes to the delegate instead of the away assignee", async () => {
    const now = new Date();
    const start = new Date(now.getTime() - 60_000).toISOString();
    const end = new Date(now.getTime() + 60_000).toISOString();

    await memberService.setAbsence(tenant.actors.viewer, {
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      delegateUserId: tenant.userIds.admin,
      startsAt: start,
      endsAt: end,
      note: null,
    });

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const overdueIssue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Overdue while away",
        assigneeId: tenant.userIds.viewer,
        dueAt: "2020-01-01T00:00:00.000Z",
      }),
      tenant.userIds.owner,
      number,
    );

    const seen: unknown[] = [];
    const off = subscribe("issue.overdue", (p) => {
      seen.push(p);
    });

    await runOverdueIssueJob(new Date());
    off();

    expect(seen).toEqual(
      expect.arrayContaining([expect.objectContaining({ issueId: overdueIssue.id, assigneeId: tenant.userIds.viewer })]),
    );

    await memberService.clearAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.viewer);
  });

  it("member removal drops the absence and clears delegations pointing at the removed member", async () => {
    const t = await createTenant("absence-removal", "growth");
    const now = new Date();
    const start = new Date(now.getTime() - 60_000).toISOString();
    const end = new Date(now.getTime() + 60_000).toISOString();

    await memberService.setAbsence(t.actors.viewer, {
      orgId: t.org.id,
      userId: t.userIds.viewer,
      delegateUserId: t.userIds.admin,
      startsAt: start,
      endsAt: end,
      note: null,
    });
    await memberService.setAbsence(t.actors.member, {
      orgId: t.org.id,
      userId: t.userIds.member,
      delegateUserId: t.userIds.admin,
      startsAt: start,
      endsAt: end,
      note: null,
    });

    const adminMember = await memberRepo.findMember(t.org.id, t.userIds.admin);
    if (!adminMember) throw new Error("fixture admin missing");
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: adminMember.id });

    // viewer's own absence untouched in shape, but delegate cleared
    const viewerAbsence = await memberRepo.findAbsence(t.org.id, t.userIds.viewer);
    expect(viewerAbsence?.delegateUserId).toBeNull();
    const memberAbsence = await memberRepo.findAbsence(t.org.id, t.userIds.member);
    expect(memberAbsence?.delegateUserId).toBeNull();

    // the removed admin's own absence (if they'd had one) would be gone - verify no row
    const adminMemberAbsence = await memberRepo.findAbsence(t.org.id, t.userIds.admin);
    expect(adminMemberAbsence).toBeNull();
  });
});

