it("a mention alerts both the mentioned (away) member and their delegate, deduped", async () => {
  const t = await createTenant("absence-mention", "growth");
  const now = new Date();
  const start = new Date(now.getTime() - 60_000).toISOString();
  const end = new Date(now.getTime() + 60_000).toISOString();

  await memberService.setAbsence(t.actors.viewer, {
    orgId: t.org.id,
    userId: t.userIds.viewer,
    delegateUserId: t.userIds.admin,
    startsAt: start,
    endsAt: end,
    note: null,
  });

  const issue = await issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, t.project.id, { title: "Mention while away" }),
  );

  const { emit } = await import("@/lib/event-bus");
  await emit("comment.created", {
    orgId: t.org.id,
    actorId: t.userIds.member,
    occurredAt: issue.createdAt,
    commentId: "cmt-away-mention" as never,
    issueId: issue.id,
    // mention both the away viewer AND their delegate directly, in the same comment
    mentionedUserIds: [t.userIds.viewer, t.userIds.admin],
  });

  const notificationService = await import("@/server/services/notification-service");
  const forViewer = await notificationService.listNotifications(t.actors.owner, {
    orgId: t.org.id,
    recipientId: t.userIds.viewer,
    unreadOnly: false,
    kind: ["comment_mention"],
    limit: 25,
    cursor: null,
  });
  const forAdmin = await notificationService.listNotifications(t.actors.owner, {
    orgId: t.org.id,
    recipientId: t.userIds.admin,
    unreadOnly: false,
    kind: ["comment_mention"],
    limit: 25,
    cursor: null,
  });

  expect(forViewer.items).toHaveLength(1);
  // exactly one alert for admin, even though mentioned directly AND is the delegate
  expect(forAdmin.items).toHaveLength(1);
});

